-- API-002 integration keys: owner-created, read-only application credentials with a fixed
-- scope catalogue. Only SHA-256 hashes of secrets are stored. A rotated secret keeps its
-- row (revoked) so a later attempt with it is refused and logged against its key.
CREATE TABLE st_integrations (
 id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 label TEXT NOT NULL, scopes TEXT NOT NULL CHECK(json_valid(scopes)), location TEXT NOT NULL,
 events TEXT NOT NULL CHECK(json_valid(events)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, revoked_at INTEGER
);
CREATE TABLE st_integration_secrets (
 token_hash TEXT PRIMARY KEY, integration_id TEXT NOT NULL REFERENCES st_integrations(id),
 created_at INTEGER NOT NULL, revoked_at INTEGER
);
-- The owner's usage and failure log: the newest 100 requests per key. It holds the key,
-- method, path, status and refusal code only, never a query string or member data.
CREATE TABLE st_integration_requests (
 seq INTEGER PRIMARY KEY, integration_id TEXT NOT NULL REFERENCES st_integrations(id),
 at INTEGER NOT NULL, method TEXT NOT NULL, route TEXT NOT NULL, status INTEGER NOT NULL, code TEXT
);
CREATE INDEX st_integration_requests_key ON st_integration_requests(integration_id, seq);
-- Counted requests of the last rolling 60 seconds, per key, for the rate limit.
CREATE TABLE st_integration_rate (integration_id TEXT NOT NULL REFERENCES st_integrations(id), at INTEGER NOT NULL);
CREATE INDEX st_integration_rate_key ON st_integration_rate(integration_id, at);

-- SEC-004: second factors for privileged sign-in. Authenticator-app secrets are
-- sealed under the installation's MFA_KEY (AES-GCM), never the session secret;
-- passkeys keep public keys; recovery codes keep SHA-256 hashes. Factors,
-- per-session checks and passkey challenges are credentials: they are excluded
-- from archives, so a restored installation sends every person back to
-- enrollment. The audit rows and the finance grant are ordinary records.
CREATE TABLE st_mfa_factors (
 id TEXT PRIMARY KEY, operator_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('totp','passkey')), label TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('pending','active')),
 sealed_secret TEXT, last_step INTEGER NOT NULL DEFAULT 0,
 credential_id TEXT UNIQUE, public_key TEXT CHECK(public_key IS NULL OR json_valid(public_key)), sign_count INTEGER NOT NULL DEFAULT 0,
 created_at INTEGER NOT NULL, confirmed_at INTEGER,
 CHECK((kind = 'totp' AND sealed_secret IS NOT NULL) OR (kind = 'passkey' AND credential_id IS NOT NULL AND public_key IS NOT NULL))
);
CREATE INDEX st_mfa_factors_operator ON st_mfa_factors(operator_id);
CREATE TABLE st_mfa_recovery (
 operator_id TEXT NOT NULL, code_hash TEXT NOT NULL, used_at INTEGER,
 PRIMARY KEY(operator_id, code_hash)
);
CREATE TABLE st_mfa_sessions (
 session_id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, verified_at INTEGER NOT NULL, method TEXT NOT NULL
);
CREATE INDEX st_mfa_sessions_operator ON st_mfa_sessions(operator_id);
CREATE TABLE st_mfa_challenges (
 id TEXT PRIMARY KEY, operator_id TEXT NOT NULL, session_id TEXT NOT NULL,
 purpose TEXT NOT NULL CHECK(purpose IN ('register','verify')), challenge TEXT NOT NULL, expires_at INTEGER NOT NULL
);
-- A finance user is a staff identity: the owner grants it to an invited person, who then
-- reaches the revenue and collections report and nothing else.
CREATE TABLE st_finance_users (
 person_id TEXT PRIMARY KEY, granted_by TEXT NOT NULL, granted_at INTEGER NOT NULL
);
CREATE TABLE st_security_audit (
 id TEXT PRIMARY KEY, at INTEGER NOT NULL, actor_id TEXT NOT NULL, actor_email TEXT NOT NULL,
 action TEXT NOT NULL, subject_id TEXT NOT NULL, subject_email TEXT, detail TEXT NOT NULL CHECK(json_valid(detail))
);
CREATE INDEX st_security_audit_at ON st_security_audit(at);

-- STUDIO-002: a manager is a staff identity the owner grants to an invited person for named
-- locations; it reaches the revenue and attendance reports for those locations and nothing else.
-- An integration key may name several locations; a key made before locations existed keeps its
-- single location column and reads only that one.
CREATE TABLE st_managers (
 person_id TEXT PRIMARY KEY, location_ids TEXT NOT NULL CHECK(json_valid(location_ids)), granted_by TEXT NOT NULL, granted_at INTEGER NOT NULL
);
ALTER TABLE st_integrations ADD COLUMN locations TEXT CHECK(locations IS NULL OR json_valid(locations));

-- Apply as a NEW numbered migration after any oa_sessions rebuild.
-- Never infer inactivity from missing credentials: older sessions may have been
-- pruned. Existing operators receive a full inactivity window from this upgrade.
ALTER TABLE oa_operators ADD COLUMN last_signin_at INTEGER;
UPDATE oa_operators SET last_signin_at=MAX(
 created_at, CAST(strftime('%s','now') AS INTEGER)*1000+999,
 COALESCE((SELECT MAX(created_at) FROM oa_sessions WHERE operator_id=oa_operators.id),0)
);
CREATE TRIGGER oa_record_last_signin AFTER INSERT ON oa_sessions
 BEGIN UPDATE oa_operators SET last_signin_at=NEW.created_at
 WHERE id=NEW.operator_id AND (last_signin_at IS NULL OR last_signin_at<NEW.created_at); END;

-- Apply as a NEW numbered migration. Authority and audit are durable, not sessions.
CREATE TABLE IF NOT EXISTS oa_policy_approvals (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version_hash TEXT NOT NULL,
 definition TEXT NOT NULL, actions TEXT NOT NULL,
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 approved_at INTEGER NOT NULL, revoked_at INTEGER,
 session_kind TEXT NOT NULL, revoke_reason TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS oa_policy_live ON oa_policy_approvals(policy_id) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS oa_policy_runs (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version_hash TEXT,
 approval_id TEXT REFERENCES oa_policy_approvals(id), approved_by TEXT,
 started_at INTEGER NOT NULL, finished_at INTEGER,
 status TEXT NOT NULL CHECK(status IN ('running','completed','refused','failed')), error TEXT,
 admitted INTEGER NOT NULL DEFAULT 0, repeats INTEGER NOT NULL DEFAULT 1, last_seen_at INTEGER
);
CREATE INDEX IF NOT EXISTS oa_policy_runs_time ON oa_policy_runs(started_at DESC);
CREATE INDEX IF NOT EXISTS oa_policy_action_run ON oa_auth_audit(CASE WHEN json_valid(value) THEN json_extract(value,'$.runId') END,action);

ALTER TABLE rer_dependency_installation ADD COLUMN keys_sealed INTEGER NOT NULL DEFAULT 0 CHECK(keys_sealed IN (0,1));
-- Nonsecret version history lets restored rows name an unavailable retired key
-- without confusing ciphertext tampering or a wrong current secret with restore.
ALTER TABLE rer_dependency_installation ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(key_ids) AND json_type(key_ids)='array');

-- Retain each expiring personal completion as an immutable receipt.
DROP INDEX st_acknowledgement;
CREATE UNIQUE INDEX st_acknowledgement ON st_records(
  json_extract(data,'$.personId'),
  json_extract(data,'$.waiverId'),
  COALESCE(json_extract(data,'$.validUntil'),'')
) WHERE kind='acknowledgement';
